import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { EmptyList } from '~/widgets/empty-list';
import { useCmmntyManageReadOneonOneListInfiniteQuery } from '~/entities/community/api/use-cmmnty-manage-read-oneon-one-list-infinite-query';
import { CommunityParams } from '~/entities/community/model/types';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { parseToDate } from '~/shared/lib/web-view-bridge';
import { PATHS } from '~/shared/routes/paths';

export const InquiryContent = () => {
  const { navigate } = useNavigate();
  const [ref, inView] = useInView();
  const { data: list, fetchNextPage, hasNextPage, refetch } = useCmmntyManageReadOneonOneListInfiniteQuery({});

  const fnGoDetail = (item: CommunityParams) => () => {
    navigate(`${PATHS.community.inquiryDetail}${item.nttManageId}`, { state: item.nttManageId });
  };

  useEffect(() => {
    if (hasNextPage && inView) fetchNextPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasNextPage, inView]);

  const flattenList = list?.pages.map((page) => page?.result?.list).flat() || [];
  if (!list || flattenList.length === 0) {
    return <EmptyList message={i18n.t('validation:noInquiries')} reset={refetch} />;
  }

  return (
    <>
      <ul>
        {flattenList?.map(
          (item, index) =>
            item && (
              <li key={`li_${item.nttManageId}_${index}`} ref={index + 1 === flattenList.length ? ref : null}>
                <div className="qna-label">
                  {item.ctgryNm && <span className="qna-tag">{item.ctgryNm}</span>}{' '}
                  <span className={`qna-sttus ${item.answerCn ? 'on' : ''}`}>
                    {item.answerCn ? i18n.t('answerCompleted') : i18n.t('inProgress')}
                  </span>
                </div>
                <button type="button" onClick={fnGoDetail(item)} data-testid="go-detail-button">
                  <p>{item.nttSj}</p>
                  <span>{parseToDate(item.registDt, 'yyyy.MM.dd')}</span>
                </button>
              </li>
            ),
        )}
      </ul>
    </>
  );
};
