import { InfiniteData, useInfiniteQuery } from '@tanstack/react-query';
import axios, { AxiosError } from 'axios';
import { DEFAULT_COMMUNITY_PAGING } from '~/entities/community/model/constants';
import { CommunityListResponse, CommunitySearch } from '~/entities/community/model/types';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { SortDirection } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

const cmmntyManageReadOneonOneList = ({ paging, search }: CommunitySearch) => {
  return resultify(
    axios.post<CommunityListResponse>(`${API_URLS.cmmntyManage('readOneonOneList')}`, {
      paging,
      search,
    }),
  );
};

export const useCmmntyManageReadOneonOneListInfiniteQuery = (
  { paging = DEFAULT_COMMUNITY_PAGING, search }: CommunitySearch,
  options?: InfiniteQueryOptions<
    CommunityListResponse,
    AxiosError,
    InfiniteData<CommunityListResponse>,
    readonly unknown[],
    CommunitySearch
  >,
) => {
  return useInfiniteQuery<
    CommunityListResponse,
    AxiosError,
    InfiniteData<CommunityListResponse>,
    readonly unknown[],
    CommunitySearch
  >({
    queryKey: queries.community.oneOnOneList({ paging, search }).queryKey,
    queryFn: ({ pageParam = { paging, search } }) => cmmntyManageReadOneonOneList(pageParam),
    initialPageParam: { paging, search },
    getNextPageParam: (lastPage: CommunityListResponse) => {
      if (
        Number(lastPage?.result?.paging?.totalPageCount ?? 0) <= Number(lastPage?.result?.paging?.currentPageNo ?? 0)
      ) {
        return undefined;
      }
      return {
        paging: {
          ...lastPage?.result?.paging,
          orderBy: {
            columnList: [{ columnName: 'registDt', sortDirection: SortDirection.내림차순 }],
            toSnakeCase: true,
          },
          currentPageNo: Number(lastPage?.result?.paging?.currentPageNo ?? 0) + 1,
        },
        search,
      };
    },
    ...options,
  });
};
